import{_ as l,o as a,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Developer Monthly 2020-10-07","description":"","frontmatter":{"title":"Ceph Developer Monthly 2020-10-07","date":"2020-10-07T00:00:00.000Z","updated":"2020-10-10T00:00:00.000Z","tags":["Ceph","高效追踪","分布式存储","CephFS","RocksDB","CRUSH算法","高可用性","可伸缩性","分布式NVMe命名空间"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Developer_Monthly_2020-10-07.md","filePath":"posts/2020/Ceph_Developer_Monthly_2020-10-07.md","lastUpdated":1780460162000}'),i={name:"posts/2020/Ceph_Developer_Monthly_2020-10-07.md"};function r(n,e,s,h,p,_){return a(),t("div",null,[...e[0]||(e[0]=[o('<p>本次会议主要讨论了高效追踪与分布式存储系统优化，涵盖了以下关键内容：</p><h3 id="高效追踪系统" tabindex="-1">高效追踪系统 <a class="header-anchor" href="#高效追踪系统" aria-label="Permalink to &quot;高效追踪系统&quot;">​</a></h3><ul><li><strong>追踪重要性</strong>： 用于解决系统中未知的性能问题，特别是在高并发系统中。</li><li><strong>现有追踪系统局限性</strong>： 日志系统数据量大，动态添加追踪点需要重新编译，字符串操作开销大。</li><li><strong>设计要求</strong>： 简单易用，无锁操作，高效收集数据，支持在线事件收集过滤。</li><li><strong>实施细节</strong>： 使用全局变量，支持在线添加和移除过滤器，双缓冲技术减少同步需求。</li><li><strong>未来工作</strong>： 集成到现有工具如Wireshark，与现有追踪系统兼容或替代。</li></ul><h3 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h3><ul><li>设计一个既高效又易于使用的追踪系统。</li><li>在不增加系统负担的情况下收集和分析追踪数据。</li><li>与现有工具和系统（如Jaeger）集成或替代。</li></ul><h3 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h3><ul><li>开发一个原型来测试和验证高效追踪系统的概念。</li><li>考虑使用现有开源项目（如SPDK的ADM参考实现）作为基础。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>开发和测试高效追踪系统的原型。</li><li>探索与现有追踪工具的集成或替代方案。</li><li>根据反馈和测试结果调整和优化系统设计。</li></ul><h3 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h3><ul><li>分布式NVMe命名空间（ADN）的概念和实现，旨在优化存储系统的连接性和性能。</li><li>如何将ADN集成到Ceph中，以及可能的技术挑战和解决方案。</li></ul><p>通过本次会议，团队对高效追踪系统的需求和设计有了更清晰的认识，并制定了初步的实施计划。同时，会议还讨论了分布式NVMe命名空间的技术挑战和解决方案。</p>',12)])])}const c=l(i,[["render",r]]);export{u as __pageData,c as default};
